// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BillingHold) predicate.BillingHold {
	return predicate.BillingHold(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BillingHold) predicate.BillingHold {
	return predicate.BillingHold(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BillingHold) predicate.BillingHold {
	return predicate.BillingHold(sql.NotPredicates(p))
}
